INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1698384, 230122, 11518, '<td valign="top">Out of focus.  The eyes HAVE to be in focus in portraits, looks like you focused on the T-shirt.</td>', 'Out of focus.  The eyes HAVE to be in focus in portraits, looks like you focused on the T-shirt.', '2005-09-12 10:11:32.000000', NULL, 1),
(1698385, 229378, 14656, '<td valign="top">Excessively large border does nothing for me.</td>', 'Excessively large border does nothing for me.', '2005-09-12 10:11:43.000000', NULL, 1),
(1698386, 230111, 15711, '<td valign="top">Nice downshot with up up gaze.  The softness and luminiscent skin tones are quite pretty. I find the dark khaki hat and zip jacket more of a detrament than an addition to the shot. I see that you were going for the same color as her eyes, but they are so pretty that I think I''d at least crop out part of the jacket to expose just her upper chest area. She is a real beauty!!</td>', 'Nice downshot with up up gaze.  The softness and luminiscent skin tones are quite pretty. I find the dark khaki hat and zip jacket more of a detrament than an addition to the shot. I see that you were going for the same color as her eyes, but they are so pretty that I think I''d at least crop out part of the jacket to expose just her upper chest area. She is a real beauty!!', '2005-09-12 10:12:01.000000', NULL, 1),
(1698388, 229062, 9111, '<td valign="top">I LOVE this photo!!    ::HUG::    Esme is such a doll!!</td>', 'I LOVE this photo!!    ::HUG::    Esme is such a doll!!', '2005-09-12 10:12:13.000000', NULL, 1),
(1698390, 230101, 40820, '<td valign="top">sharp...with super detail...the reflection makes one linger...great shot</td>', 'sharp...with super detail...the reflection makes one linger...great shot', '2005-09-12 10:12:31.000000', NULL, 1),
(1698391, 229044, 41066, '<td valign="top">Great title!  I love the passion in his eyes, he really wants to do a great punch! 8</td>', 'Great title!  I love the passion in his eyes, he really wants to do a great punch! 8', '2005-09-12 10:12:32.000000', NULL, 1),
(1698393, 230111, 41845, '<td valign="top">I like the way you have captured the eyes of your model, lovely angle.</td>', 'I like the way you have captured the eyes of your model, lovely angle.', '2005-09-12 10:12:54.000000', NULL, 1),
(1698394, 229867, 11518, '<td valign="top">Veru cute!  Great composition.  Only criticism is the light is a tad harsh.</td>', 'Veru cute!  Great composition.  Only criticism is the light is a tad harsh.', '2005-09-12 10:13:14.000000', NULL, 1),
(1698395, 229401, 14656, '<td valign="top">Colors really pop!</td>', 'Colors really pop!', '2005-09-12 10:13:24.000000', NULL, 1),
(1698396, 227656, 41066, '<td valign="top">Beautiful photo, one to treasure for years to come.  I would probably go a little lighter on the border as it takes the eyes away from your precious baby. 8</td>', 'Beautiful photo, one to treasure for years to come.  I would probably go a little lighter on the border as it takes the eyes away from your precious baby. 8', '2005-09-12 10:13:27.000000', NULL, 1),
(1698398, 230086, 40820, '<td valign="top">this image is a little too much on the soft side<br/></td>', 'this image is a little too much on the soft side', '2005-09-12 10:13:44.000000', NULL, 1),
(1698399, 230145, 11518, '<td valign="top">Distracting background.</td>', 'Distracting background.', '2005-09-12 10:13:46.000000', NULL, 1),
