INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1701039, 230343, 41675, '<td valign="top">Nice portrait of a pretty woman. I like the composition and background.</td>', 'Nice portrait of a pretty woman. I like the composition and background.', '2005-09-12 21:04:21.000000', NULL, 1),
(1701040, 230113, 43256, '<td valign="top">This is too cute.</td>', 'This is too cute.', '2005-09-12 21:04:47.000000', NULL, 1),
