(1701046, 228125, 41675, '<td valign="top">Nice, crisp portrait - would work nicely for a hair or makeup ad in a magazine.</td>', 'Nice, crisp portrait - would work nicely for a hair or makeup ad in a magazine.', '2005-09-12 21:05:52.000000', NULL, 1),
(1701047, 230360, 43256, '<td valign="top">Very neat.  It seems unreal.</td>', 'Very neat.  It seems unreal.', '2005-09-12 21:05:56.000000', NULL, 1),
(1701049, 229884, 41675, '<td valign="top">At first I thought...hmmmm...now that I''ve looked at it for a few minutes...kinda cool. Lots of photo-editing fun. My favorite part is the eyes.</td>', 'At first I thought...hmmmm...now that I''ve looked at it for a few minutes...kinda cool. Lots of photo-editing fun. My favorite part is the eyes.', '2005-09-12 21:06:54.000000', NULL, 1),
