(1702561, 229937, 34442, '<td valign="top">When doing portraits of people with a single subjiect, you want to ensure that their eyes are absolutely in focus</td>', 'When doing portraits of people with a single subjiect, you want to ensure that their eyes are absolutely in focus', '2005-09-13 03:54:06.000000', NULL, 1),
(1702568, 228788, 34442, '<td valign="top">I would have liked to see a bigger picture</td>', 'I would have liked to see a bigger picture', '2005-09-13 04:00:15.000000', NULL, 1),
