(1703970, 229730, 43565, '<td valign="top">I don''t like the lighting</td>', 'I don''t like the lighting', '2005-09-13 14:12:23.000000', NULL, 1),
(1703971, 229722, 16106, '<td valign="top">lol Im not sure which portrait I like better, the guys expression is great. A bit more room on the left side near the critters nose would help IMHO</td>', 'lol Im not sure which portrait I like better, the guys expression is great. A bit more room on the left side near the critters nose would help IMHO', '2005-09-13 14:12:40.000000', NULL, 1),
