(1716276, 230289, 37529, '<td valign="top">I think if you croppedto just his face this would have been top finisher.</td>', 'I think if you croppedto just his face this would have been top finisher.', '2005-09-17 13:10:11.000000', NULL, 1),
(1716277, 230111, 10985, '<td valign="top">Very good. Top ten, I''m sure.</td>', 'Very good. Top ten, I''m sure.', '2005-09-17 13:10:18.000000', NULL, 1),
(1716280, 230246, 10985, '<td valign="top">Ah, a two-in-one, hugh? Very good lighting and composition. This is good!</td>', 'Ah, a two-in-one, hugh? Very good lighting and composition. This is good!', '2005-09-17 13:12:07.000000', NULL, 1),
